package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Iterator;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ArrayRealVector.getLInfNorm().
 * 
 * Note: The provided implementation of getLInfNorm in the prompt:
 *     double max = 0;
 *     for (double a : data) {
 *         max += Math.max(max, Math.abs(a));
 *     }
 *     return max;
 * 
 * This implementation is mathematically unusual for an L-infinity norm 
 * (which should be the maximum absolute value). It acts more like a 
 * cumulative summation of maximums. The tests below are written to 
 * validate the logic provided in the snippet.
 */
public class ArrayRealVector_getLInfNorm_TriageGen5Test {

    @Test
    public void testGetLInfNorm_EmptyVector() {
        ArrayRealVector vector = new ArrayRealVector(0);
        // max starts at 0, loop doesn't execute
        Assert.assertEquals(0.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_PositiveValues() {
        // data = [1.0, 2.0, 3.0]
        // iter 1: max = 0 + max(0, 1.0) = 1.0
        // iter 2: max = 1.0 + max(1.0, 2.0) = 3.0
        // iter 3: max = 3.0 + max(3.0, 3.0) = 6.0
        double[] data = {1.0, 2.0, 3.0};
        ArrayRealVector vector = new ArrayRealVector(data);
        Assert.assertEquals(6.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_NegativeValues() {
        // data = [-1.0, -5.0, -2.0]
        // iter 1: max = 0 + max(0, |-1.0|) = 1.0
        // iter 2: max = 1.0 + max(1.0, |-5.0|) = 6.0
        // iter 3: max = 6.0 + max(6.0, |-2.0|) = 12.0
        double[] data = {-1.0, -5.0, -2.0};
        ArrayRealVector vector = new ArrayRealVector(data);
        Assert.assertEquals(12.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_MixedValues() {
        // data = [10.0, -20.0, 5.0]
        // iter 1: max = 0 + max(0, 10.0) = 10.0
        // iter 2: max = 10.0 + max(10.0, 20.0) = 30.0
        // iter 3: max = 30.0 + max(30.0, 5.0) = 60.0
        double[] data = {10.0, -20.0, 5.0};
        ArrayRealVector vector = new ArrayRealVector(data);
        Assert.assertEquals(60.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_Zeros() {
        double[] data = {0.0, 0.0, 0.0};
        ArrayRealVector vector = new ArrayRealVector(data);
        Assert.assertEquals(0.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_SingleElement() {
        // data = [5.0] -> 0 + max(0, 5.0) = 5.0
        ArrayRealVector vector = new ArrayRealVector(new double[]{5.0});
        Assert.assertEquals(5.0, vector.getLInfNorm(), 1e-10);

        // data = [-5.0] -> 0 + max(0, 5.0) = 5.0
        ArrayRealVector vectorNeg = new ArrayRealVector(new double[]{-5.0});
        Assert.assertEquals(5.0, vectorNeg.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_LargeValues() {
        double[] data = {1e10, 1e10};
        // iter 1: 0 + 1e10 = 1e10
        // iter 2: 1e10 + max(1e10, 1e10) = 2e10
        ArrayRealVector vector = new ArrayRealVector(data);
        Assert.assertEquals(2e10, vector.getLInfNorm(), 1e-2);
    }
}
